l.push(fill(t.ag_seg_pos_fecha, { fecha: esc(reg.f || '-') }));
const par = first.cargas_descargas || [];
if (par.length) {
  const p = par[0];
  l.push('');
  l.push(fill(t.lbl_proxima, { tipo: p.OrigDest === 'O' ? t.lbl_carga : t.lbl_descarga, fecha: String(p.Fecha || '').slice(8, 10) + '/' + String(p.Fecha || '').slice(5, 7) + ' ' + String(p.Fecha || '').slice(11, 16) }));
  l.push(esc(String(p.Empresa || '').trim()) + (p.Poblacion ? ' (' + esc(p.Poblacion) + ')' : ''));
  if (p.kms !== undefined) { l.push(fill(t.lbl_distancia, { kms: p.kms, tiempo: ht(p.tiempo) })); }
}
return [{ json: { ok: true, text: l.join('\n'), lat: lat, lon: lon, id: seg.id } }];

