function fill(s, o) { return String(s || '').replace(/\{(\w+)\}/g, function (m, k) { return (o[k] !== undefined && o[k] !== null) ? o[k] : ''; }); }
function ht(s) { const m = String(s || '').match(/^(?:(\d+)d )?(\d+):(\d+)/); if (!m) return String(s || '-'); return (m[1] ? m[1] + ' d ' : '') + Number(m[2]) + ' h ' + m[3] + ' min'; }
